123	#[derive(Debug, PartialEq, Eq, Clone)]
124	enum ParseState<'a> {
125	    /// Parsing a value done, there is no state to record.
126	    ValueDone,
127	
128	    /// Parsing a positional argument after `--`. `Pos(pos_index`, `takes_num_args`)
129	    Pos((usize, usize)),
130	
131	    /// Parsing a optional flag argument
132	    Opt((&'a clap::Arg, usize)),
133	}
