347	fn complete_arg_value(
348	    value: Result<&str, &OsStr>,
349	    arg: &clap::Arg,
350	    current_dir: Option<&std::path::Path>,
351	    arg_index: usize,
352	) -> Vec<CompletionCandidate> {
353	    let mut values = Vec::new();
354	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
355	
356	    let (prefix, value) =
357	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
358	
359	    let value_os = match value {
360	        Ok(value) => OsStr::new(value),
361	        Err(value_os) => value_os,
362	    };
363	
364	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
365	        values.extend(completer.complete_at(arg_index, value_os));
366	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
367	        values.extend(complete_value_candidates(
368	            value_os,
369	            completer.value_candidates(),
370	        ));
371	    } else if let Some(possible_values) = possible_values(arg) {
372	        if let Ok(value) = value {
373	            values.extend(complete_candidates_str(
374	                value,
375	                possible_value_candidates(possible_values),
376	            ));
377	        }
378	    } else {
379	        match arg.get_value_hint() {
380	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
381	                // Should not complete
382	            }
383	            clap::ValueHint::AnyPath => {
384	                values.extend(complete_path(value_os, current_dir, &|_| true));
385	            }
386	            clap::ValueHint::FilePath => {
387	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
388	            }
389	            clap::ValueHint::DirPath => {
390	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
391	            }
392	            clap::ValueHint::ExecutablePath => {
393	                use is_executable::IsExecutable;
394	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
395	            }
396	            clap::ValueHint::CommandName
397	            | clap::ValueHint::CommandString
398	            | clap::ValueHint::CommandWithArguments
399	            | clap::ValueHint::Username
400	            | clap::ValueHint::Hostname
401	            | clap::ValueHint::Url
402	            | clap::ValueHint::EmailAddress => {
403	                // No completion implementation
404	            }
405	            _ => {
406	                // Safe-ish fallback
407	                values.extend(complete_path(value_os, current_dir, &|_| true));
408	            }
409	        }
410	
411	        values.sort();
412	    }
413	
414	    if let Some(prefix) = prefix {
415	        values = values
416	            .into_iter()
417	            .map(|comp| comp.add_prefix(prefix))
418	            .collect();
419	    }
420	    values = values
421	        .into_iter()
422	        .map(|comp| {
423	            if comp.get_tag().is_some() {
424	                comp
425	            } else {
426	                comp.tag(Some(arg.to_string().into()))
427	            }
428	        })
429	        .collect();
430	
431	    debug!("complete_arg_value: values={values:?}");
432	    values
433	}
