476	fn complete_subcommand(value: &str, cmd: &clap::Command) -> Vec<CompletionCandidate> {
477	    debug!(
478	        "complete_subcommand: cmd={:?}, value={:?}",
479	        cmd.get_name(),
480	        value
481	    );
482	
483	    let mut scs: Vec<CompletionCandidate> = subcommands(cmd)
484	        .into_iter()
485	        .filter(|x| x.get_value().starts_with(value))
486	        .collect();
487	    if cmd.is_allow_external_subcommands_set() {
488	        let external_completer = cmd.get::<SubcommandCandidates>();
489	        if let Some(completer) = external_completer {
490	            scs.extend(complete_value_candidates_str(
491	                value,
492	                completer.value_candidates(),
493	            ));
494	        }
495	    }
496	
497	    scs.sort();
498	    scs.dedup();
499	    scs
500	}
