570	/// Get the possible values for completion
571	fn possible_values(
572	    a: &clap::Arg,
573	) -> Option<Box<dyn Iterator<Item = clap::builder::PossibleValue> + '_>> {
574	    if !a.get_num_args().expect("built").takes_values() {
575	        None
576	    } else {
577	        a.get_value_parser().possible_values()
578	    }
579	}
