262	impl<I, T> From<I> for RawArgs
263	where
264	    I: Iterator<Item = T>,
265	    T: Into<OsString>,
266	{
267	    fn from(val: I) -> Self {
268	        Self {
269	            items: val.map(|x| x.into()).collect(),
270	        }
271	    }
272	}
