397	/// Walk through short flags within a [`ParsedArg`]
398	#[derive(Clone, Debug)]
399	pub struct ShortFlags<'s> {
400	    inner: &'s OsStr,
401	    utf8_prefix: std::str::CharIndices<'s>,
