    assert!(complete_escape_tool(&["tool", "--", "alpha", ""]).is_empty());
    assert!(complete_escape_tool(&["tool", "run", "--", "one", "two", ""]).is_empty());
}

#[test]
fn escape_blocks_subcommand_dispatch() {
